class DSU {
  constructor(n) {
    this.parent = Array.from({ length: n }, (_, i) => i);
    this.count = n;
  }
  // no path compression: pure walk to root
  find(x) {
    if (this.parent[x] === x) return x;
    return this.find(this.parent[x]);
  }
  // naive: always hang ra under rb, no rank
  union(a, b) {
    const ra = this.find(a), rb = this.find(b);
    if (ra === rb) return false;
    this.parent[ra] = rb;
    this.count--;
    return true;
  }
}
